import heapq

def match(orders):
    trades = []
    active = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':...}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    seq_counter = 0

    def match_incoming(incoming_id, side, price, qty, order_type):
        nonlocal trades
        if side == 'buy':
            heap = sell_heap
            while qty > 0 and heap:
                top_price, top_seq, sid = heap[0]
                info = active.get(sid)
                if info is None or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                resting_price = info['price']
                if order_type != 'market' and resting_price > price:
                    break
                # valid match, pop it
                heapq.heappop(heap)
                trade_qty = min(qty, info['qty'])
                trades.append([incoming_id, sid, resting_price, trade_qty])
                qty -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (top_price, top_seq, sid))
                else:
                    if sid in active:
                        del active[sid]
        else:
            heap = buy_heap
            while qty > 0 and heap:
                neg_price, top_seq, bid = heap[0]
                info = active.get(bid)
                if info is None or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                resting_price = info['price']
                if order_type != 'market' and resting_price < price:
                    break
                heapq.heappop(heap)
                trade_qty = min(qty, info['qty'])
                trades.append([bid, incoming_id, resting_price, trade_qty])
                qty -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (neg_price, top_seq, bid))
                else:
                    if bid in active:
                        del active[bid]
        return qty

    for order in orders:
        op = order[0]
        if op == 'cancel':
            oid = order[1]
            if oid in active:
                del active[oid]
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, price, qty, 'limit')
            if remaining > 0:
                seq_counter += 1
                active[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
        elif op == 'ioc':
            _, oid, side, price, qty = order
            match_incoming(oid, side, price, qty, 'ioc')
            # remainder discarded
        elif op == 'market':
            _, oid, side, qty = order
            match_incoming(oid, side, None, qty, 'market')
            # remainder discarded

    return trades

